{
 "summary": "The file states four NP-hardness results for promise problems under deterministic poly-time many-one (Karp) reductions on bit strings: GapCVP in ℓ2 with gap n^{1/400}, binary nearest codeword with gap n^{1/200}, binary syndrome decoding with gap n^{1/200}, and ℓp GapCVP (rational p ≥ 1) with gap n^{1/(200p)}. The most important caveat is that `binarySyndromeDecodingIsNPHard` carries the false hypothesis `(1 : ℕ) = 0`. That makes it vacuous, so the syndrome-decoding half of Corollary 15 is not actually formalized. The other three statements look faithful.",
 "glossary": [
  {"decl": "GapCVP.IsNP", "line": 49, "plain": "L ∈ NP: there is a polynomial certificate-length bound and a poly-time (TM2) verifier V such that L(x) ⇔ ∃c, |c| ≤ bound(|x|) ∧ V(x,c) = true.", "standard_concept": "NP (verifier definition)", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.PromiseReduction", "line": 140, "plain": "A poly-time map f on bit strings with x ∈ L ⇒ f(x) ∈ YES and x ∉ L ⇒ f(x) ∈ NO.", "standard_concept": "Karp reduction to a promise problem", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.IsNPHardPromise", "line": 147, "plain": "Every NP language Karp-reduces to the promise problem.", "standard_concept": "NP-hardness of a promise problem", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.gapCVP400Promise", "line": 135, "plain": "YES: encodings of (n>0, nonsingular B ∈ Z^{n×n}, integer target t, r>0) with ∃v ∈ Z^n, ‖Bv−t‖₂² ≤ r². NO: the same, but ∀v, (n^{1/400} r)² < ‖Bv−t‖₂².", "standard_concept": "GapCVP_{n^{1/400}} in ℓ2", "matches_standard": "yes", "note": "The squared comparisons are equivalent to the unsquared ones because both sides are nonnegative (r > 0). Disjointness is proved by sorry."},
  {"decl": "GapCVP.Comparator.binaryNearestCodewordPromise", "line": 187, "plain": "YES: (G ∈ F2^{N×k}, u, R>0, N>0) with ∃c, wt(u − Gc) ≤ R. NO: ∀c, N^{1/200} R < wt(u − Gc).", "standard_concept": "Gap nearest codeword over F2 with gap n^{1/200}", "matches_standard": "yes", "note": "The code is the column span of G, which is equivalent to the paper's row-span convention."},
  {"decl": "GapCVP.Comparator.binarySyndromeDecodingPromise", "line": 244, "plain": "YES: ∃x, Hx = b ∧ wt(x) ≤ R. NO: Hx = b is consistent and every solution has wt(x) > N^{1/200} R.", "standard_concept": "Gap syndrome decoding over F2", "matches_standard": "yes", "note": "The consistency requirement in NO matches the paper's proof sketch."},
  {"decl": "GapCVP.Comparator.finitePGapCVPPromise", "line": 287, "plain": "YES: well-formed (B, t ∈ Q^n, r) with ∃v, ‖t − Bv‖_p ≤ r. NO: ∀v, n^{1/(200p)} r < ‖t − Bv‖_p.", "standard_concept": "GapCVP in ℓp", "matches_standard": "unclear", "note": "Rational targets are allowed here (there is no hasIntegerTarget). The exponent 1/(200p) is not in the excerpt."}
 ],
 "lean_claims": [
  {"theorem": "gapCVP400IsNPHard", "line": 153, "plain": "GapCVP in ℓ2 with gap n^{1/400}, on integer-target nonsingular instances, is NP-hard under poly-time Karp reductions."},
  {"theorem": "binaryNearestCodewordIsNPHard", "line": 212, "plain": "Binary gap nearest codeword with gap N^{1/200} is NP-hard."},
  {"theorem": "binarySyndromeDecodingIsNPHard", "line": 268, "plain": "If 1 = 0 in ℕ, then binary gap syndrome decoding is NP-hard. This is vacuous."},
  {"theorem": "finitePNormGapCVPIsNPHard", "line": 307, "plain": "For every rational p ≥ 1, ℓp GapCVP with gap n^{1/(200p)} is NP-hard."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1", "plain": "GapCVP_{n^{1/400}} (ℓ2, nonsingular integer basis, integer target, rational radius) is NP-hard under deterministic poly-time many-one reductions."},
  {"ref": "Corollary 15", "plain": "Binary nearest codeword and binary syndrome decoding are NP-hard to approximate within n^{1/200}."},
  {"ref": "Section 7 fixed finite norm consequence", "plain": "A fixed finite ℓp norm consequence; the exact statement is not in the excerpt."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1", "lean_theorem": "gapCVP400IsNPHard", "relation": "equivalent", "why": "Same instance set and gap; the squared form is equivalent."},
  {"paper_ref": "Corollary 15 (nearest codeword)", "lean_theorem": "binaryNearestCodewordIsNPHard", "relation": "equivalent", "why": "Same gap and block-length parameter."},
  {"paper_ref": "Corollary 15 (syndrome decoding)", "lean_theorem": "binarySyndromeDecodingIsNPHard", "relation": "lean_weaker", "why": "The false hypothesis 1 = 0 makes the statement vacuous."},
  {"paper_ref": "Section 7 fixed finite norm consequence", "lean_theorem": "finitePNormGapCVPIsNPHard", "relation": "different", "why": "The paper's exact statement is not in the excerpt, and Lean allows rational targets."}
 ],
 "flags": [
  {"id": "F1", "category": "assumption", "severity": "high", "decl": "binarySyndromeDecodingIsNPHard", "line": 268, "paper_ref": "Corollary 15", "explanation": "The hypothesis `hbase : (1 : ℕ) = 0` is false, so the theorem is trivially provable and says nothing about syndrome decoding.", "polarity": "lean weaker", "probe_idea": "Prove `binarySyndromeDecodingIsNPHard` without the hypothesis, i.e. `theorem : IsNPHardPromise binarySyndromeDecodingPromise`."},
  {"id": "F2", "category": "other", "severity": "low", "decl": "gapCVP400Promise", "line": 138, "paper_ref": null, "explanation": "The `disjoint` fields of all four promise definitions are discharged by `sorry` (lines 138, 210, 266, 305). The fields appear true, since the gap factor is ≥ 1 for dimension ≥ 1, provided the encodings are injective. That injectivity is unverified.", "polarity": "n/a", "probe_idea": "Prove `Function.Injective encodeInstance` and then the disjointness lemmas."},
  {"id": "F3", "category": "definition-mismatch", "severity": "low", "decl": "finitePGapCVPPromise", "line": 287, "paper_ref": "Section 7 fixed finite norm consequence", "explanation": "Targets may be rational here, unlike Theorem 1, which uses integer targets. Rational targets can be scaled to integers, so this is minor. The exponent 1/(200p) cannot be checked against the excerpt.", "polarity": "unclear", "probe_idea": null}
 ],
